    const project=point=>({x:(point[0]-transform.origin[0])*transform.scale[0]+transform.translate[0],y:(transform.origin[1]-point[1])*transform.scale[1]+transform.translate[1]}),corners=[project([bounds[0],bounds[1]]),project([bounds[0],bounds[3]]),project([bounds[2],bounds[1]]),project([bounds[2],bounds[3]])],xs=corners.map(point=>point.x),ys=corners.map(point=>point.y),padding=2,minX=Math.min(...xs)-padding,maxX=Math.max(...xs)+padding,minY=Math.min(...ys)-padding,maxY=Math.max(...ys)+padding;
