  function geographicDemandJourney(originId,destinationId){
    let routes=geographicDemandJourneyCache.get(originId);if(!routes){const adjacency=new Map();for(const line of state.lines){if(line.broken||!line.locomotive||!line.passengerCars||!line.path?.length)continue;const weight=Math.max(1,line.path.length-2);for(const[from,to]of[[line.a.id,line.b.id],[line.b.id,line.a.id]]){if(!adjacency.has(from))adjacency.set(from,[]);adjacency.get(from).push({to,lineId:line.id,weight});}}for(const edges of adjacency.values())edges.sort((a,b)=>a.weight-b.weight||a.lineId.localeCompare(b.lineId)||a.to.localeCompare(b.to));const distance=new Map([[originId,0]]),previous=new Map(),queue=[originId];while(queue.length){queue.sort((a,b)=>distance.get(a)-distance.get(b)||a.localeCompare(b));const current=queue.shift();for(const edge of adjacency.get(current)||[]){const candidate=distance.get(current)+edge.weight,known=distance.get(edge.to);if(known===undefined||candidate<known){distance.set(edge.to,candidate);previous.set(edge.to,{stationId:current,lineId:edge.lineId});if(!queue.includes(edge.to))queue.push(edge.to);}}}routes={distance,previous};geographicDemandJourneyCache.set(originId,routes);}if(!routes.distance.has(destinationId))return null;const stationsPath=[destinationId],linesPath=[];let current=destinationId;while(current!==originId){const step=routes.previous.get(current);if(!step)return null;linesPath.push(step.lineId);stationsPath.push(step.stationId);current=step.stationId;}stationsPath.reverse();linesPath.reverse();return{stations:stationsPath,lines:linesPath,distance:routes.distance.get(destinationId),transfers:0};
  }

