  function restoreConstruction(snapshot){if(snapshot.grid){GRID.cols=snapshot.grid.cols;GRID.rows=snapshot.grid.rows;}state.tracks=new Set(snapshot.tracks);stations.forEach(s=>{const area=snapshot.areas[s.id];if(area)s.area={...area};else delete s.area;});state.lines.forEach(line=>{line.path=findPath(line.a,line.b);line.broken=!line.path;if(line.broken)line.status='LINE BROKEN';else if(line.status==='LINE BROKEN')line.status=line.locomotive&&line.passengerCars?'LOADING':'NO TRAIN';});invalidatePassengerJourneys();clearInspector();updateHUD();}
