      if(eff)eff.textContent=`${metricEfficiency()}%`;if(flow)flow.textContent=recentThroughput();if(pax)pax.textContent=state.metrics.passengersMoved;if(xfer)xfer.textContent=state.metrics.transfers||0;if(timeEl)timeEl.textContent=RailwayClock.format(railwayTime());
      if(waiting)waiting.textContent=passengerStats.waiting.toLocaleString();if(onboard)onboard.textContent=passengerStats.onboard.toLocaleString();if(onboardNote)onboardNote.textContent=`${Math.round(passengerStats.loadFactor*100)}% of modeled capacity`;
      if(demandValue)demandValue.textContent=demand?Math.round(demand.passengersPerHour).toLocaleString():'—';if(demandNote)demandNote.textContent=demand?`passengers / hour · ${demand.multiplier.toFixed(2)}× time profile`:'no ODM demand product';if(demandPeriod)demandPeriod.textContent=demand?`${demand.instant.weekday.slice(0,3).toUpperCase()} · NOW ${demand.instant.time.slice(0,5)}`:'NO DATA';
      drawDemandGraph(document.getElementById('demand-graph'),demand);drawMetricGraph(document.getElementById('throughput-graph'),'passengers',COLORS.signal);
