  function recordSimulationIntervals(previousTick){if(Math.floor(previousTick/4)!==Math.floor(state.tick/4))state.metrics.history.push({tick:state.tick,passengers:state.metrics.passengersMoved});if(state.metrics.history.length>300)state.metrics.history.splice(0,state.metrics.history.length-300);if(Math.floor(previousTick/240)!==Math.floor(state.tick/240))RailSaveManager.autosave(saveRepository,namedSaveState(),{scenario:state.scenario,tick:state.tick});}
  function stepSimulation(){const previousTick=state.tick;state.tick++;processStations(REAL_STEP_SECONDS);state.lines.forEach(l=>updateLine(l,REAL_STEP_SECONDS));recordSimulationIntervals(previousTick);}
  function queueVirtualDemandBatch(seconds,tick){virtualDemandQueue.push({seconds,instant:RailwayClock.atStep(railwayClock,tick),cities:stations.filter(station=>station.type==='CITY'),index:0});}
  function processVirtualDemandSlice(){const job=virtualDemandQueue[0];if(!job)return;const size=state.speed>=512?12:24,end=Math.min(job.cities.length,job.index+size);spawnPassengers(job.seconds,job.cities.slice(job.index,end),job.instant);job.index=end;if(job.index>=job.cities.length)virtualDemandQueue.shift();}
