  function visualFrameInterval(){return state.speed>=512?250:state.speed>=256?100:state.speed>=64?1000/30:0;}
  function trainFrameInterval(){return state.speed>=64?1000/30:0;}
  function tick(now){const frameStarted=performance.now(),raw=Math.min((now-state.lastTime)/1000,.25);state.lastTime=now;let stepped=false,simulationStarted=performance.now();if(!state.paused&&state.scenario!=='gb-national'){state.accumulator+=raw*state.speed;const availableSteps=Math.floor(state.accumulator/REAL_STEP_SECONDS),timetableAnalysis=Boolean(state.workingDay);if(availableSteps>0){const processedSteps=timetableAnalysis?availableSteps:Math.min(availableSteps,MAX_STEPS_PER_FRAME);if(timetableAnalysis)advanceTimetableSimulation(processedSteps);else for(let count=0;count<processedSteps;count++)stepSimulation();state.accumulator-=processedSteps*REAL_STEP_SECONDS;stepped=true;}}processVirtualDemandSlice();recordPerformanceSample(performanceTelemetry.simulation,performance.now()-simulationStarted);const annotationInterval=visualFrameInterval(),trainInterval=trainFrameInterval(),drawAnnotations=!annotationInterval||now-lastVisualFrameAt>=annotationInterval,drawTrain=!trainInterval||now-lastTrainFrameAt>=trainInterval;if(drawAnnotations||drawTrain){if(drawAnnotations)lastVisualFrameAt=now;if(drawTrain)lastTrainFrameAt=now;if(stepped)updateHUD();refreshInspector(now);const renderStarted=performance.now();if(drawAnnotations)renderAnnotations();if(drawTrain)renderTrainLayer();recordPerformanceSample(performanceTelemetry.render,performance.now()-renderStarted);recordPerformanceSample(performanceTelemetry.frames,performance.now()-frameStarted);}else performanceTelemetry.visualFramesSkipped++;if(PERFORMANCE_PROFILING&&now-lastPerformanceProfileAt>=1000){lastPerformanceProfileAt=now;document.documentElement.dataset.railPerformance=JSON.stringify(browserPerformanceSnapshot());}requestAnimationFrame(tick);}

  function normalizeRect(a,b){const x=Math.min(a.x,b.x),y=Math.min(a.y,b.y);return{x,y,w:Math.abs(a.x-b.x)+1,h:Math.abs(a.y-b.y)+1};}
  function rasterCells(a,b){const out=[];let x=a.x,y=a.y;while(x!==b.x){x+=Math.sign(b.x-x);out.push({x,y});}while(y!==b.y){y+=Math.sign(b.y-y);out.push({x,y});}return out;}
