  function renderSaveManager(){saveUIModel=RailSaveManager.refresh(saveRepository,{selectedSlotId:saveUIModel?.selectedSlotId});const slots=document.getElementById('save-slot-list'),autosaves=document.getElementById('autosave-list'),recoveryPanel=document.getElementById('save-recovery');recoveryPanel.classList.add('hidden');document.getElementById('save-status').textContent=saveUIModel.status==='ready'?`${saveUIModel.cards.length} SLOT${saveUIModel.cards.length===1?'':'S'}`:'RECOVERY NEEDED';slots.innerHTML=saveUIModel.cards.length?saveUIModel.cards.map(card=>`<button class="save-row ${card.id===saveUIModel.selectedSlotId?'selected':''}" data-slot="${escapeHTML(card.id)}"><b>${escapeHTML(card.name)}</b><small>${formatSavedAt(card.savedAt)}</small></button>`).join(''):'<div class="management-empty">No named saves yet.</div>';autosaves.innerHTML=saveUIModel.autosaveHistory.length?saveUIModel.autosaveHistory.map(item=>`<button class="save-row ${item.id===selectedAutosaveId?'selected':''}" data-autosave="${escapeHTML(item.id)}"><b>${item.label}</b><small>${formatSavedAt(item.savedAt)}</small></button>`).join(''):'<div class="management-empty">Autosaves appear every modelled hour.</div>';slots.querySelectorAll('[data-slot]').forEach(button=>button.onclick=()=>{saveUIModel={...saveUIModel,selectedSlotId:button.dataset.slot};selectedAutosaveId=null;renderSaveManager();});autosaves.querySelectorAll('[data-autosave]').forEach(button=>button.onclick=()=>{selectedAutosaveId=button.dataset.autosave;renderSaveManager();const recovery=document.getElementById('save-recovery');recovery.innerHTML=`Autosave selected. <button>RESTORE ${formatSavedAt(saveUIModel.autosaveHistory.find(item=>item.id===selectedAutosaveId)?.savedAt)}</button>`;recovery.classList.remove('hidden');recovery.querySelector('button').onclick=()=>{try{restoreNamedEnvelope(saveRepository.loadAutosave(selectedAutosaveId));closeSaveManager();toast('Autosave restored',`Returned to ${RailwayClock.format(railwayTime())}.`);}catch{toast('Autosave invalid','This recovery point could not be loaded.');}};});if(saveUIModel.corruption){recoveryPanel.textContent=`Save index problem: ${saveUIModel.corruption.error.message}`;recoveryPanel.classList.remove('hidden');}}
  function openSaveManager(){document.getElementById('save-manager').classList.remove('hidden');document.getElementById('onboarding').classList.add('hidden');document.getElementById('save-name').value=`${state.scenario[0].toUpperCase()+state.scenario.slice(1)} network`;renderSaveManager();setTimeout(()=>document.getElementById('save-name').focus(),0);}
